INSERT INTO "comunicados" ("id", "condominio_id", "titulo", "conteudo", "tipo", "data_publicacao", "data_expiracao", "criado_por", "ativo", "created_at", "updated_at") VALUES ('9e2f13ca-7819-4c48-a0de-b5413a10d6fe', '59c1d16b-2eea-4ba7-a06a-f90bd3310de8', 'Conserto do portão de garagem', 'Pedimos aos condôminos que precisarem sair com seus carros no período entre 8 e 12h, deixar seu carro na rua de frente, pois dentro deste período estaremos fazendo manutenção do portão de garagem. Não será possível entrar ou sair enquanto a manutenção estiver sendo feita.                                Agradecemos a compreensão de todos.', 'manutencao', '2026-06-17T11:40:29.471804+00:00', '2026-06-20T00:00:00+00:00', 'c3726637-94a6-4c06-8817-f7f1d38045b6', TRUE, '2026-06-17T11:40:29.471804+00:00', '2026-06-18T11:46:35.291014+00:00');
